        var y = drops[i]
        ctx.fillStyle = 'rgba(63, 182, 255, 0.42)'
        ctx.fillText(chars.charAt((Math.random() * 16) | 0), x, y)
        if (y > h + 20 && Math.random() > 0.975) drops[i] = -20
        drops[i] += 11 + (i % 4)
